    if isinstance(_n, _ast.Name) and _n.id in _BANNED_NAMES:
        raise AssertionError("rule: " + _n.id + " used")
    if isinstance(_n, _ast.Attribute) and _n.attr in _BANNED_NAMES and _n.attr not in _NAME_ONLY:
        raise AssertionError("rule: ." + _n.attr + " used")
    if isinstance(_n, _ast.Constant) and isinstance(_n.value, str) and any(_b in _n.value for _b in _BANNED_STRINGS):
        raise AssertionError("rule: grader internals named in a string")
    if isinstance(_n, _ast.Import):
        for _a in _n.names:
            if _a.name.split(".")[0] in _BANNED_MODS:
