    try:
        return ("ok", _FORMAT(v, s))
    except ValueError:
        return ("ValueError", None)

def _check(v, s):
    w = _want(v, s)
    try:
        g = ("ok", fmt(v, s))
    except ValueError:
        g = ("ValueError", None)
    if w != g:
        raise AssertionError((v, s, "expected", w[1] if w[0] == "ok" else "ValueError",
                              "got", g[1] if g[0] == "ok" else "ValueError"))

def _rfloat(R):
    k = R.random()
    if k < 0.12:
        return R.choice([0.0, -0.0, float("inf"), -float("inf"), float("nan"), 5e-324, 1e16, 1e22,
                         0.5, 2.5, 0.125, 1.5, -2.5, 9.9999995, 0.0001, 1e-5, 999999.5, 9.5, 0.05,
                         123456789.0, 1e-7, 0.375, 2.675, 1.0, -1.0, 100.0, 1e300, 0.1])
    if k < 0.3:
        while True:
            x = _struct.unpack("d", _struct.pack("Q", R.getrandbits(64)))[0]
            if not _math.isnan(x) or R.random() < 0.05:
                return x
    if k < 0.6:
        return R.choice([1, -1]) * R.randint(0, 10 ** R.randint(0, 12)) / 10 ** R.randint(0, 8)
    return R.choice([1, -1]) * 10 ** R.uniform(-12, 25)

def _rint(R):
    return R.choice([1, -1]) * R.choice([0, 1, 7, 255, 1234, 4096, 65535,
                                          R.randint(0, 10 ** R.randint(1, 25))])

def _rspec(R, types, extra_bad=False):
    s = ""
    if R.random() < 0.4:
        if R.random() < 0.6:
            s += R.choice("x*0z=<#. ")
        s += R.choice("<>=^")
    if R.random() < 0.4:
        s += R.choice("+- ")
    if R.random() < 0.15:
        s += "z"
    if R.random() < 0.25:
        s += "#"
    if R.random() < 0.35:
        s += "0"
    if R.random() < 0.65:
        s += str(R.randint(0, 30))
    if R.random() < 0.35:
        s += R.choice(",_")
    if R.random() < 0.5:
        s += "." + str(R.randint(0, 20))
    if R.random() < 0.9:
        s += R.choice(types)
    if extra_bad and R.random() < 0.25:
        k = R.randint(0, len(s))
        s = s[:k] + R.choice([",", "_", ".", "z", "#", "s", "d", "f", "=", "0", ".x", "q"]) + s[k:]
    return s

