    from fractions import Fraction
    import re

    EMPTY = None
    CELL_RE = re.compile(r"[A-Z](?:[1-9][0-9]?)\Z")
    NUM_LIT = re.compile(r"-?[0-9]+(?:\.[0-9]+)?\Z")
