    class Err(str):
        pass

    def E(code):
        return Err(code)

    class ParseError(Exception):
        pass

    def tokenize(s):
        toks, i, n = [], 0, len(s)
        while i < n:
            c = s[i]
            if c == " ":
                i += 1
                continue
            if c.isdigit() and c in "0123456789":
                j = i
                while j < n and s[j] in "0123456789":
                    j += 1
                if j < n and s[j] == ".":
                    k = j + 1
                    while k < n and s[k] in "0123456789":
                        k += 1
                    if k == j + 1:
                        raise ParseError
                    j = k
                toks.append(("num", Fraction(s[i:j])))
                i = j
                continue
