                j = i
                while j < n and (("a" <= s[j] <= "z") or ("A" <= s[j] <= "Z") or s[j] in "0123456789"):
                    j += 1
                w = s[i:j]
                if CELL_RE.match(w):
                    toks.append(("cell", w))
                elif w in ("TRUE", "FALSE"):
                    toks.append(("bool", w == "TRUE"))
                elif w in FUNCS and j < n and s[j] == "(":
                    toks.append(("func", w))
                else:
                    raise ParseError
                i = j
                continue
            if c == '"':
                j = s.find('"', i + 1)
                if j < 0:
                    raise ParseError
                toks.append(("str", s[i + 1:j]))
                i = j + 1
                continue
