            if two in ("<>", "<=", ">="):
                toks.append(("op", two))
                i += 2
                continue
            if c in "=<>&+-*/^(),:":
                toks.append(("op", c))
                i += 1
                continue
            raise ParseError
        return toks

    def parse(src):
        toks = tokenize(src)
