        elif k == "range":
            acc.update(cells_of_range(node[1], node[2]))
        elif k in ("cmp", "cat", "arith"):
            refs_of(node[2], acc)
            refs_of(node[3], acc)
        elif k in ("neg", "pos", "paren"):
            refs_of(node[1], acc)
        elif k == "func":
            for a in node[2]:
