    LIMIT = Fraction(10) ** 100

    def big(x):
        return x

    def num(v):
        if isinstance(v, Err):
            return v
        if v is EMPTY:
            return Fraction(0)
        if isinstance(v, bool):
            return Fraction(int(v))
        if isinstance(v, Fraction):
            return v
        return E("#VALUE!")

    def text(v):
        if isinstance(v, Err):
            return v
        return render(v)

    def typerank(v):
        if isinstance(v, Fraction):
            return 0
        if isinstance(v, bool):
            return 2 + int(v)
        return 1

    def value_of(cell):
